#!/usr/bin/env python3
"""Generate/check the immutable per-texture consumer catalogue; IDs and masks only."""
import argparse
import json
from pathlib import Path

from audit_texture_consumers import FAMILIES

PIECES = 5


def files(report):
    if report["families"] != FAMILIES or not report["rows"]:
        raise ValueError("texture consumer family contract changed; review TextureConsumers::Family")
    prefix = (
        "// Generated by texture_consumers_catalogue.py; static IDs/masks, no original game content.\n"
        '#include "games/slus_20909_crash_twinsanity/hle/graphics/textures/texture_consumers_catalogue.h"\n'
        "#include <iterator>\n\nnamespace title {\n")
    result = {"identity.cpp": (prefix +
        "MaterialCertificate::Archive TextureConsumersCatalogue::Identity() {\n"
        "    return {\n"
        f'    "{report["archive_header_sha256"]}",\n'
        f'    "{report["archive_data_sha256"]}"\n'
        "    };\n}\n}  // namespace title\n")}
    rows = []
    previous = -1
    for row in report["rows"]:
        texture = int(row["texture"], 16)
        if texture <= previous or not row["families"] or row["materials"] > 0xffff or row["appearances"] > 0xffff:
            raise ValueError("texture catalogue rows must be sorted, unique and bounded")
        previous = texture
        rows.append(f'{{0x{texture:08x}, 0x{row["families"]:04x}, 0x{row["shaders"]:016x}ull, '
                    f'{row["materials"]}, {row["appearances"]}}},')
    stride = (len(rows) + PIECES - 1) // PIECES
    if stride > 985:
        raise ValueError("catalogue partition budget changed; review source layout")
    for i in range(PIECES):
        result[f"rows_{i}.cpp"] = (prefix +
            "namespace {\n"
            "constexpr TextureConsumers::Entry rows[] = {\n" +
            "\n".join(rows[i * stride:(i + 1) * stride]) + "\n};\n}  // namespace\n"
            f"TextureConsumersCatalogue::Rows TextureConsumersCatalogue::Rows{i}() {{\n"
            "    return {rows, std::size(rows)};\n}\n}  // namespace title\n")
    census = {key: report[key] for key in (
        "archive_header_sha256", "archive_data_sha256", "families", "texture_ids", "appearances",
        "family_counts", "shader_type_counts", "exclusive_certified_textures", "certified_textures",
        "single_family_textures", "scope")}
    result["../texture_consumers_census.json"] = json.dumps(census, indent=2) + "\n"
    return result


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("inventory", type=Path)
    parser.add_argument("directory", type=Path)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    args.directory.mkdir(parents=True, exist_ok=True)
    for name, text in files(json.loads(args.inventory.read_text())).items():
        path = args.directory / name
        if args.check:
            if not path.exists() or path.read_text() != text:
                raise ValueError(f"catalogue differs: {name}")
        else:
            path.write_text(text)
    print("texture consumer catalogue matches complete inventory" if args.check
          else "texture consumer catalogue generated")


if __name__ == "__main__":
    main()
